-- Compras y aperturas necesitan conservar la zona física del lote.
ALTER TABLE "inventory_lots" ADD COLUMN IF NOT EXISTS "zona_id" BIGINT;

CREATE INDEX IF NOT EXISTS "inventory_lots_negocio_zona_producto_estado_fecha_idx"
  ON "inventory_lots" ("negocio_id", "zona_id", "product_id", "estado", "recibido_at");

CREATE TABLE IF NOT EXISTS "inventory_lot_transfers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "negocio_id" BIGINT NOT NULL,
  "lote_id" BIGINT NOT NULL,
  "zona_origen_id" BIGINT,
  "zona_destino_id" BIGINT NOT NULL,
  "cantidad" DECIMAL(14,4) NOT NULL,
  "fecha" DATE NOT NULL,
  "motivo" TEXT,
  "usuario_id" BIGINT,
  "creado_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "inventory_lot_transfers_negocio_fecha_idx"
  ON "inventory_lot_transfers" ("negocio_id", "fecha");
CREATE INDEX IF NOT EXISTS "inventory_lot_transfers_negocio_lote_idx"
  ON "inventory_lot_transfers" ("negocio_id", "lote_id");
CREATE INDEX IF NOT EXISTS "inventory_lot_transfers_negocio_destino_fecha_idx"
  ON "inventory_lot_transfers" ("negocio_id", "zona_destino_id", "fecha");

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'inventory_lots_zona_id_fkey') THEN
    ALTER TABLE "inventory_lots" ADD CONSTRAINT "inventory_lots_zona_id_fkey"
      FOREIGN KEY ("zona_id") REFERENCES "zonas_inventario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'inventory_lot_transfers_negocio_id_fkey') THEN
    ALTER TABLE "inventory_lot_transfers" ADD CONSTRAINT "inventory_lot_transfers_negocio_id_fkey"
      FOREIGN KEY ("negocio_id") REFERENCES "negocios"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'inventory_lot_transfers_lote_id_fkey') THEN
    ALTER TABLE "inventory_lot_transfers" ADD CONSTRAINT "inventory_lot_transfers_lote_id_fkey"
      FOREIGN KEY ("lote_id") REFERENCES "inventory_lots"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'inventory_lot_transfers_zona_origen_id_fkey') THEN
    ALTER TABLE "inventory_lot_transfers" ADD CONSTRAINT "inventory_lot_transfers_zona_origen_id_fkey"
      FOREIGN KEY ("zona_origen_id") REFERENCES "zonas_inventario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'inventory_lot_transfers_zona_destino_id_fkey') THEN
    ALTER TABLE "inventory_lot_transfers" ADD CONSTRAINT "inventory_lot_transfers_zona_destino_id_fkey"
      FOREIGN KEY ("zona_destino_id") REFERENCES "zonas_inventario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
  END IF;
END $$;
